-- Demo: um usuário-modelo guarda o escritório de exemplo; "Entrar como demo" cria um usuário
-- anônimo e chama clonar_demo(), que copia os dados do modelo para ele.

-- Modelo: sem senha nem e-mail, não consegue entrar. Os tokens vazios evitam erro do Auth ao ler NULL.
insert into auth.users (id, instance_id, aud, role, is_anonymous, created_at, updated_at,
  confirmation_token, recovery_token, email_change_token_new, email_change)
values ('00000000-0000-0000-0000-00000000de00', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
  false, now(), now(), '', '', '', '')
on conflict (id) do nothing;

-- Copia clientes, itens (com sugestões e cálculos) e alíquotas do modelo para auth.uid(), com ids novos.
-- Idempotente: quem já tem clientes não recebe outra cópia (duas chamadas simultâneas esbarram no unique de CNPJ).
create function clonar_demo() returns void
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  modelo constant uuid := '00000000-0000-0000-0000-00000000de00';
begin
  if uid is null then
    raise exception 'clonar_demo exige um usuário autenticado';
  end if;
  if not coalesce((auth.jwt()->>'is_anonymous')::boolean, false) then
    return; -- a demo é só para a sessão anônima do botão "Entrar como demo"
  end if;
  if exists (select 1 from clientes where user_id = uid) then
    return;
  end if;

  create temp table mapa on commit drop as
    select id as antigo, gen_random_uuid() as novo from clientes where user_id = modelo;

  insert into clientes (id, user_id, razao_social, cnpj, regime, uf, municipio_ibge, c_ativ_sn, p_ibs_sn, p_cbs_sn)
  select m.novo, uid, c.razao_social, c.cnpj, c.regime, c.uf, c.municipio_ibge, c.c_ativ_sn, c.p_ibs_sn, c.p_cbs_sn
  from clientes c join mapa m on m.antigo = c.id;

  insert into itens (user_id, cliente_id, codigo, descricao, ncm, nbs, c_trib_nac, ocorrencias, ultimo_valor,
    situacao, origem, cst, cclasstrib, is_cst, is_cclasstrib, condicao, opcoes, calculos)
  select uid, m.novo, i.codigo, i.descricao, i.ncm, i.nbs, i.c_trib_nac, i.ocorrencias, i.ultimo_valor,
    i.situacao, i.origem, i.cst, i.cclasstrib, i.is_cst, i.is_cclasstrib, i.condicao, i.opcoes, i.calculos
  from itens i join mapa m on m.antigo = i.cliente_id;

  insert into aliquotas_estimadas (user_id, cbs, ibs_uf, ibs_mun, is_ad_valorem)
  select uid, cbs, ibs_uf, ibs_mun, is_ad_valorem from aliquotas_estimadas where user_id = modelo
  on conflict (user_id) do nothing;
end $$;

revoke execute on function clonar_demo() from public, anon;
grant execute on function clonar_demo() to authenticated;

-- Limpeza diária das contas de demo com mais de 7 dias (o cascade leva os dados junto).
create extension if not exists pg_cron;
select cron.schedule('limpar-demos', '0 4 * * *',
  $$delete from auth.users where is_anonymous and created_at < now() - interval '7 days'$$);

